function validate([schedule]) {
  if (!Array.isArray(schedule) || schedule.length < 1 || schedule.length > 50) return 'schedule needs 1 to 50 employees.';
  for (const employee of schedule) {
    if (!Array.isArray(employee) || employee.length < 1 || employee.length > 50) return 'Each employee has 1 to 50 intervals.';
    for (let j = 0; j < employee.length; j++) {
      const pair = employee[j];
      if (!Array.isArray(pair) || pair.length !== 2 || !Number.isInteger(pair[0]) || !Number.isInteger(pair[1])) return 'Each interval is a pair [start, end] of whole numbers.';
      if (pair[0] < 0 || pair[0] >= pair[1] || pair[1] > 100000000) return 'Each interval needs 0 <= start < end <= 10^8.';
      if (j > 0 && pair[0] < employee[j - 1][1]) return "An employee's intervals must be sorted and must not overlap.";
    }
  }
  return null;
}

