function adapt(input, solve, kit) {
  // LeetCode's Interval: a plain object with start and end.
  class Interval {
    constructor(start, end) {
      this.start = start;
      this.end = end;
    }
  }
  globalThis.Interval = Interval;
  const [schedule] = input;
  const answer = solve(schedule.map(employee => employee.map(([start, end]) => new Interval(start, end))));
  if (!Array.isArray(answer)) throw new Error('employeeFreeTime must return a list of Interval objects.');
  return answer.map(item => {
    if (!item || typeof item.start !== 'number' || typeof item.end !== 'number') throw new Error('Each returned item must be an Interval with number fields start and end.');
    return [item.start, item.end];
  });
}

