function employeeFreeTime(schedule) {
  // Cut the timeline at every endpoint and test each piece against every interval.
  const all = schedule.flat();
  const points = [...new Set(all.flatMap(i => [i.start, i.end]))].sort((a, b) => a - b);
  const result = [];
  for (let k = 0; k + 1 < points.length; k++) {
    const p = points[k], q = points[k + 1];
    const busy = all.some(i => i.start <= p && q <= i.end);
    if (busy) continue;
    const last = result[result.length - 1];
    if (last && last.end === p) last.end = q;
    else result.push(new Interval(p, q));
  }
  return result;
}

