function generate(rand, size) {
  const schedule = [];
  if (size === 'small') {
    const people = 1 + Math.floor(rand() * 4);
    for (let i = 0; i < people; i++) {
      const count = 1 + Math.floor(rand() * 4);
      const employee = [];
      let position = -1;
      for (let j = 0; j < count; j++) {
        const start = position + 1 + Math.floor(rand() * 4);
        const end = start + 1 + Math.floor(rand() * 4);
        employee.push([start, end]);
        position = end;
      }
      schedule.push(employee);
    }
    return [schedule];
  }
  const LIMIT = 100000000;
  const people = 50;
  const count = 40;
  const step = 2 * LIMIT / count / 1.05;
  // Each employee works roughly a share of the day; a log-uniform share gives anything from many gaps to none.
  const share = 10 ** (-3.5 + 3 * rand());
  for (let i = 0; i < people; i++) {
    const employee = [];
    let position = -1;
    for (let j = 0; j < count; j++) {
      const start = position + 1 + Math.floor(rand() * step * (1 - share));
      const end = start + 1 + Math.floor(rand() * step * share);
      if (end > LIMIT) break;
      employee.push([start, end]);
      position = end;
    }
    if (employee.length === 0) employee.push([0, 1 + Math.floor(rand() * 1000)]);
    schedule.push(employee);
  }
  return [schedule];
}
